using System.Data;
using BlazorApp1.Models;
using BlazorApp1.Services;
using Microsoft.Data.SqlClient;
using Microsoft.Extensions.Configuration;

Console.WriteLine("Starting product seeding...");

// Konfiguration laden (Pfad ggf. anpassen)
var config = new ConfigurationBuilder()
    .AddJsonFile("appsettings.json", optional: false, reloadOnChange: false)
    .Build();

var connectionString = config.GetConnectionString("Sql");
if (string.IsNullOrWhiteSpace(connectionString))
{
    Console.WriteLine("ConnectionStrings:Sql not found in appsettings.json.");
    return;
}

List<Product> productsToSeed = new()
    {
        new() { Id = 1, Name = "Oculus Quest 3", Description = "Single-origin Arabica, 1kg", Price = 14.90m, ImageBase64 = "", Stock = 25 },
        new() { Id = 2, Name = "DJI Pocket 3", Description = "Porcelain set of 2", Price = 9.50m, ImageBase64 = "", Stock = 40 },
    };

try
{
    using var connection = new SqlConnection(connectionString);
    await connection.OpenAsync();
    
    using (var deleteCmd = new SqlCommand("DELETE FROM Products", connection))
    {
        await deleteCmd.ExecuteNonQueryAsync();
    }

    const string insertSql = @"
INSERT INTO Products (Name, Description, Price, ImageBase64, Stock)
VALUES (@Name, @Description, @Price, @ImageBase64, @Stock);";

    foreach (var p in productsToSeed)
    {
        using var cmd = new SqlCommand(insertSql, connection);
        cmd.Parameters.Add(new SqlParameter("@Name", SqlDbType.NVarChar, 200) { Value = p.Name });
        cmd.Parameters.Add(new SqlParameter("@Description", SqlDbType.NVarChar, 2000)
        {
            Value = string.IsNullOrEmpty(p.Description) ? DBNull.Value : p.Description
        });
        cmd.Parameters.Add(new SqlParameter("@Price", SqlDbType.Decimal)
        {
            Precision = 18,
            Scale = 2,
            Value = p.Price
        });
        cmd.Parameters.Add(new SqlParameter("@ImageBase64", SqlDbType.NVarChar, -1)
        {
            Value = string.IsNullOrEmpty(p.ImageBase64) ? DBNull.Value : p.ImageBase64
        });
        cmd.Parameters.Add(new SqlParameter("@Stock", SqlDbType.Int) { Value = p.Stock });

        await cmd.ExecuteNonQueryAsync();
    }

    Console.WriteLine($"Seeded {productsToSeed.Count} products into database.");
}
catch (Exception ex)
{
    Console.WriteLine("Error while seeding: " + ex.Message);
}

Console.WriteLine("Seeding finished.");